begin;
create or replace function private.has_staff_role(required_role text) returns boolean language sql stable security definer set search_path = public, private as $$ select exists (select 1 from public.user_staff_roles usr join public.staff_roles sr on sr.id=usr.role_id where usr.user_id=auth.uid() and sr.name=required_role); $$;
create or replace function private.has_permission(resource_name text, action_name text) returns boolean language sql stable security definer set search_path = public, private as $$ select exists (select 1 from public.user_staff_roles usr join public.staff_role_permissions srp on srp.role_id=usr.role_id join public.permissions p on p.id=srp.permission_id where usr.user_id=auth.uid() and p.resource=resource_name and p.action=action_name) or exists (select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','super_admin','platform_admin')); $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path = public, private as $$ select exists (select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','super_admin','platform_admin')) or private.has_staff_role('Super Admin'); $$;
commit;
